def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    rows = [r for r in range(R) if len(set(g[r])) == 1 and g[r][0] != 0]
    cols = [c for c in range(C) if len({g[r][c] for r in range(R)}) == 1 and g[0][c] != 0]
    for r in rows:
        for c in range(C):
            g[r][c] = 2
    for c in cols:
        for r in range(R):
            g[r][c] = 2
    return g
